}
fn main() {
    var values = [1, 2, 3, 4]
    var total = 0
    for value in ((values)) {
        let guard = ["iteration".toString()]
        let chosen = choose(value) catch _ { continue }
        total += chosen
        if value == 3 { break }
    }
    println(total)
    values.push(5)
    println(values.len())
